# ============================================================ POLONIA
PL_URL = 'https://api.sejm.gov.pl/eli/acts/DU/2024/1741/text.html'
PL_LAW = 'Ustawa o Planie Strategicznym dla WPR 2023-2027 (Dz.U. 2023 poz. 412)'
PL_RULES = [
 ('active-farmer', 'farmer', PL_LAW + ', art. 24', ['24'], PL_URL,
  'Cuando una ayuda exige agricultor activo, no se concede a quien gestiona aeropuertos, aguas o instalaciones deportivas o recreativas permanentes, presta transporte ferroviario o negocia inmuebles, salvo que su actividad agrícola sea la principal según los registros oficiales, sus ingresos agrarios sean al menos un tercio del total (o sus pagos directos del año anterior, al menos el 5 % de sus ingresos no agrarios), o sus pagos directos del año anterior no pasen de 5.000 euros.', {'smallEur': 5000},
  tr('When an aid requires an active farmer, it is not granted to someone who manages airports, waterworks or permanent sports or leisure grounds, provides rail transport or deals in real estate, unless farming is their main activity in the official registers, farm income is at least a third of the total (or last year’s direct payments are at least 5 % of non-farm income), or last year’s direct payments did not exceed €5,000.', "Lorsqu'une aide exige un agriculteur actif, elle n'est pas accordée à qui gère des aéroports, des réseaux d'eau ou des terrains de sport ou de loisirs permanents, assure des services ferroviaires ou fait de l'immobilier, sauf si l'activité agricole est son activité principale dans les registres officiels, si le revenu agricole représente au moins un tiers du total (ou si les paiements directs de l'an dernier valent au moins 5 % du revenu non agricole), ou si ses paiements directs de l'an dernier n'excèdent pas 5 000 euros.", "Quando un aiuto richiede un agricoltore attivo, non è concesso a chi gestisce aeroporti, acquedotti o impianti sportivi o ricreativi permanenti, presta servizi ferroviari o opera nel settore immobiliare, salvo che l'attività agricola sia quella prevalente nei registri ufficiali, il reddito agricolo sia almeno un terzo del totale (o i pagamenti diretti dell'anno scorso siano almeno il 5 % del reddito non agricolo), oppure i pagamenti diretti dell'anno scorso non superino 5.000 euro.")),
 ('minimum', 'payments', PL_LAW + ', art. 25', ['25'], PL_URL,
  'Los pagos directos exigen una actividad agraria y al menos 1 ha en el apoyo básico a la renta. Excepción: sin esa hectárea se pagan igualmente si se piden pagos acoplados por animales o de bienestar y el total, antes de sanciones, es al menos el equivalente a 200 euros.', {'minHa': 1, 'minEur': 200},
  tr('Direct payments require farming activity and at least 1 ha in basic income support. Exception: without that hectare they are still paid if coupled animal or welfare payments are claimed and the total, before penalties, is at least the equivalent of €200.', "Les paiements directs exigent une activité agricole et au moins 1 ha en soutien de base au revenu. Exception : sans cet hectare ils sont versés si des paiements couplés animaux ou de bien-être sont demandés et si le total, avant sanctions, atteint au moins l'équivalent de 200 euros.", "I pagamenti diretti richiedono un'attività agricola e almeno 1 ha nel sostegno di base al reddito. Eccezione: senza quell'ettaro si pagano comunque se si chiedono pagamenti accoppiati per animali o di benessere e il totale, prima delle sanzioni, è almeno l'equivalente di 200 euro.")),
 ('parcels', 'payments', PL_LAW + ', art. 22 i 26', ['22', '26'], PL_URL,
  'Los pagos directos se conceden por parcelas agrarias de al menos 0,1 ha sobre hectáreas admisibles. Si la ayuda exige tener la tierra, cuenta la que se posee con título legal el 31 de mayo del año de la solicitud.', {'minParcelHa': 0.1, 'landDate': '05-31'},
  tr('Direct payments are granted per agricultural parcel of at least 0.1 ha on eligible hectares. If the aid requires holding the land, the land held under a legal title on 31 May of the application year counts.', "Les paiements directs sont accordés par parcelle agricole d'au moins 0,1 ha sur des hectares admissibles. Si l'aide exige de détenir la terre, compte celle détenue en vertu d'un titre légal au 31 mai de l'année de la demande.", "I pagamenti diretti si concedono per particella agricola di almeno 0,1 ha su ettari ammissibili. Se l'aiuto richiede il possesso della terra, conta quella detenuta con titolo legale il 31 maggio dell'anno della domanda.")),
 ('redistributive', 'redistributive', PL_LAW + ', art. 27', ['27'], PL_URL,
  'Pago redistributivo: lo recibe el agricultor que posee a 31 de mayo entre 1 y 300 ha en total y se paga sobre las primeras 30 ha de su tierra en el apoyo básico. Las cooperativas multiplican los límites por su número de miembros si han pasado la auditoría cooperativa en los tres últimos años.', {'minHa': 1, 'maxHa': 300, 'paidUpToHa': 30},
  tr('Redistributive payment: received by a farmer holding between 1 and 300 ha in total on 31 May and paid on the first 30 ha of their land in basic support. Cooperatives multiply the limits by their number of members if they passed the cooperative audit in the last three years.', "Paiement redistributif : reçu par l'agriculteur qui détient au total entre 1 et 300 ha au 31 mai ; il est versé sur les 30 premiers ha de sa terre en soutien de base. Les coopératives multiplient les plafonds par leur nombre de membres si elles ont passé l'audit coopératif dans les trois dernières années.", "Pagamento redistributivo: lo riceve l'agricoltore che al 31 maggio possiede in totale tra 1 e 300 ha e si paga sui primi 30 ha della sua terra nel sostegno di base. Le cooperative moltiplicano i limiti per il numero dei soci se hanno superato la revisione cooperativa negli ultimi tre anni.")),
 ('young-farmers', 'young', PL_LAW + ', art. 28', ['28'], PL_URL,
  'Jóvenes agricultores: 40 años como máximo en el primer año de solicitud, dirigir la explotación por cuenta propia y tener formación profesional, media o agraria, o tres años de experiencia en el campo. Se paga sobre la tierra del apoyo básico, durante un máximo de cinco años consecutivos; el último pago puede ser por 2027.', {'maxAge': 40, 'years': 5, 'lastCampaign': 2027},
  tr('Young farmers: aged 40 or under in the first application year, running the farm on their own account, with vocational, secondary or agricultural education or three years of farm experience. Paid on basic-support land for a maximum of five consecutive years; the last payment can be for 2027.', "Jeunes agriculteurs : 40 ans au plus la première année de demande, dirigeant l'exploitation pour leur propre compte, avec une formation professionnelle, secondaire ou agricole, ou trois ans d'expérience agricole. Versé sur les terres du soutien de base pendant cinq ans consécutifs au maximum ; le dernier paiement peut être pour 2027.", "Giovani agricoltori: non più di 40 anni nel primo anno di domanda, conducono l'azienda in proprio e hanno istruzione professionale, secondaria o agraria, o tre anni di esperienza in agricoltura. Si paga sulla terra del sostegno di base per un massimo di cinque anni consecutivi; l'ultimo pagamento può essere per il 2027.")),
 ('small-farms', 'payments', PL_LAW + ', art. 36a', ['36a'], PL_URL,
  'Pago para pequeñas explotaciones (desde junio de 2024): al menos 1 ha en el apoyo básico y como máximo 5 ha de superficie agraria a 31 de mayo. Si el agricultor no cumple esos límites, se le deniega y se resuelven sus pagos directos normales.', {'minHa': 1, 'maxHa': 5},
  tr('Small-farm payment (since June 2024): at least 1 ha in basic support and at most 5 ha of agricultural land on 31 May. If the farmer does not meet those limits it is refused and their ordinary direct payments are decided.', "Paiement pour les petites exploitations (depuis juin 2024) : au moins 1 ha en soutien de base et au plus 5 ha de surface agricole au 31 mai. Si l'agriculteur ne remplit pas ces limites, il est refusé et ses paiements directs ordinaires sont tranchés.", "Pagamento per le piccole aziende (da giugno 2024): almeno 1 ha nel sostegno di base e al massimo 5 ha di superficie agricola al 31 maggio. Se l'agricoltore non rispetta questi limiti viene negato e si decidono i suoi pagamenti diretti ordinari.")),
 ('coupled', 'associated', PL_LAW + ', art. 29', ['29'], PL_URL,
  'Los pagos acoplados cubren leguminosas, forrajeras, patata fécula, remolacha azucarera, tomate, lúpulo, fresa, lino y cáñamo por hectárea, y bovinos, ovinos y caprinos por cabeza. Bovino: animales de hasta 24 meses (pago por bovino) o hembras de más de 24 meses (pago por vaca) a 15 de mayo, mínimo 1 animal en siete voivodatos y 3 en los otros nueve, máximo 20 animales.', {'maxCattle': 20, 'ageMonths': 24, 'minHeadFew': 1, 'minHeadMany': 3},
  tr('Coupled payments cover legumes, fodder crops, starch potatoes, sugar beet, tomatoes, hops, strawberries, flax and hemp per hectare, and cattle, sheep and goats per head. Cattle: animals up to 24 months (per-bovine payment) or females over 24 months (per-cow payment) on 15 May, minimum 1 animal in seven voivodeships and 3 in the other nine, maximum 20 animals.', "Les paiements couplés couvrent légumineuses, fourrages, pommes de terre féculières, betterave sucrière, tomates, houblon, fraises, lin et chanvre à l'hectare, et bovins, ovins et caprins par tête. Bovins : animaux de 24 mois au plus (paiement par bovin) ou femelles de plus de 24 mois (paiement par vache) au 15 mai, minimum 1 animal dans sept voïvodies et 3 dans les neuf autres, maximum 20 animaux.", "I pagamenti accoppiati coprono leguminose, foraggere, patate da fecola, barbabietola da zucchero, pomodori, luppolo, fragole, lino e canapa per ettaro, e bovini, ovini e caprini per capo. Bovini: animali fino a 24 mesi (pagamento per bovino) o femmine oltre 24 mesi (pagamento per vacca) al 15 maggio, minimo 1 animale in sette voivodati e 3 negli altri nove, massimo 20 animali.")),
 ('eco-schemes', 'eco', PL_LAW + ', art. 30 i 36', ['30', '36'], PL_URL,
  'Los ecoesquemas se conceden como pagos por: zonas con plantas melíferas, agricultura del carbono y gestión de nutrientes, producción integrada, cultivo biológico (hasta 2024 «protección biológica de cultivos»), retención de agua en pastos permanentes, tierras apartadas de la producción, material de siembra élite o certificado (desde 2025) y bienestar animal. Este último premia prácticas en cerdos, bovinos, ovinos, caprinos, caballos, gallinas y pavos.', None,
  tr('Eco-schemes are granted as payments for: melliferous plant areas, carbon farming and nutrient management, integrated crop production, biological cultivation (until 2024 "biological crop protection"), water retention on permanent grassland, land taken out of production, elite or certified seed (since 2025) and animal welfare. The last rewards practices for pigs, cattle, sheep, goats, horses, hens and turkeys.', "Les écorégimes sont accordés sous forme de paiements pour : zones de plantes mellifères, agriculture du carbone et gestion des nutriments, production intégrée, culture biologique (jusqu'en 2024 « protection biologique des cultures »), rétention d'eau sur les prairies permanentes, terres retirées de la production, semences élite ou certifiées (depuis 2025) et bien-être animal. Ce dernier récompense des pratiques pour les porcs, bovins, ovins, caprins, chevaux, poules et dindes.", "Gli ecoregimi si concedono come pagamenti per: aree con piante mellifere, agricoltura del carbonio e gestione dei nutrienti, produzione integrata, coltivazione biologica (fino al 2024 «protezione biologica delle colture»), ritenzione idrica su prati permanenti, terreni ritirati dalla produzione, sementi élite o certificate (dal 2025) e benessere animale. Quest'ultimo premia pratiche per suini, bovini, ovini, caprini, cavalli, galline e tacchini.")),
 ('application', 'calendar', PL_LAW + ', art. 60 ust. 1', ['60'], PL_URL,
  'La solicitud de pagos directos se presenta del 15 de marzo al 15 de mayo. Fuera de plazo se admite hasta 25 días después, con una penalización del 1 % de la ayuda por día (sin contar sábados ni festivos). El Ministro puede ampliar el plazo por reglamento. El plazo no se restituye.', {'openMonth': 3, 'openDay': 15, 'closeMonth': 5, 'closeDay': 15, 'lateDays': 25, 'perDayPct': 1},
  tr('The direct-payment application is filed from 15 March to 15 May. Late filing is accepted up to 25 days after, with a penalty of 1 % of the aid per day (not counting Saturdays and public holidays). The Minister can extend the window by regulation. The deadline is not restored.', "La demande de paiements directs se dépose du 15 mars au 15 mai. Un dépôt tardif est accepté jusqu'à 25 jours après, avec une pénalité de 1 % de l'aide par jour (hors samedis et jours fériés). Le ministre peut prolonger le délai par règlement. Le délai n'est pas restitué.", "La domanda di pagamenti diretti si presenta dal 15 marzo al 15 maggio. È accettata in ritardo fino a 25 giorni dopo, con una penalità dell'1 % dell'aiuto al giorno (esclusi sabati e festivi). Il ministro può prorogare il termine con regolamento. Il termine non viene ripristinato.")),
 ('changes', 'calendar', PL_LAW + ', art. 60 ust. 2', ['60'], PL_URL,
  'Los cambios de la solicitud se hacen hasta el 31 de mayo (después, hasta el último día de presentación, con 1 % de penalización por día hábil) y hasta el 15 de septiembre si la Agencia ha informado de irregularidades detectadas en sus controles o en el seguimiento de superficies. La solicitud puede retirarse hasta la decisión, salvo en la parte con irregularidades o tras avisar de un control in situ.', {'month': 5, 'day': 31, 'irregularitiesMonth': 9, 'irregularitiesDay': 15},
  tr('Changes to the application can be made until 31 May (afterwards, until the last filing day, with a 1 % penalty per working day) and until 15 September if the Agency has reported irregularities found in its checks or area monitoring. The application can be withdrawn until the decision, except for the part with irregularities or after notice of an on-the-spot check.', "Les modifications de la demande se font jusqu'au 31 mai (ensuite, jusqu'au dernier jour de dépôt, avec 1 % de pénalité par jour ouvré) et jusqu'au 15 septembre si l'Agence a signalé des irrégularités relevées par ses contrôles ou le suivi des surfaces. La demande peut être retirée jusqu'à la décision, sauf pour la partie présentant des irrégularités ou après avis d'un contrôle sur place.", "Le modifiche alla domanda si fanno fino al 31 maggio (dopo, fino all'ultimo giorno di presentazione, con penalità dell'1 % per giorno lavorativo) e fino al 15 settembre se l'Agenzia ha segnalato irregolarità rilevate nei controlli o nel monitoraggio delle superfici. La domanda può essere ritirata fino alla decisione, tranne per la parte con irregolarità o dopo l'avviso di un controllo in loco.")),
 ('decision', 'calendar', PL_LAW + ', art. 67 ust. 11', ['67'], PL_URL,
  'La decisión sobre los pagos directos se dicta como máximo el 31 de mayo del año siguiente al de la solicitud.', {'month': 5, 'day': 31, 'yearOffset': 1},
  tr('The decision on direct payments is issued by 31 May of the year after the application at the latest.', "La décision sur les paiements directs est rendue au plus tard le 31 mai de l'année suivant la demande.", "La decisione sui pagamenti diretti è emessa al più tardi il 31 maggio dell'anno successivo a quello della domanda.")),
 ('advances', 'payments', 'Rozporządzenia o wypłacie zaliczek (art. 50 ust. 1 ustawy): Dz.U. 2023 poz. 2218, 2024 poz. 1518, 2025 poz. 1383, 2026 poz. 1173', ['50'], 'https://api.sejm.gov.pl/eli/acts/DU/2026/1173',
  'Cada otoño un reglamento fija los anticipos: de 2023 a 2025, el 70 % de la tasa desde el 16 de octubre; en 2026, el 75 % de una tasa estimada desde el 8 de septiembre. El anticipo de las ayudas de desarrollo rural es del 85 %. La tasa estimada de 2026 no es la definitiva.', {'2023': {'share': 0.70, 'from': '2023-10-16'}, '2024': {'share': 0.70, 'from': '2024-10-16'}, '2025': {'share': 0.70, 'from': '2025-10-16'}, '2026': {'share': 0.75, 'from': '2026-09-08'}},
  tr('Each autumn a regulation sets the advances: from 2023 to 2025, 70 % of the rate from 16 October; in 2026, 75 % of an estimated rate from 8 September. The advance on rural development aid is 85 %. The 2026 estimated rate is not the final one.', "Chaque automne, un règlement fixe les avances : de 2023 à 2025, 70 % du taux à partir du 16 octobre ; en 2026, 75 % d'un taux estimé à partir du 8 septembre. L'avance sur les aides au développement rural est de 85 %. Le taux estimé de 2026 n'est pas le taux définitif.", "Ogni autunno un regolamento fissa gli anticipi: dal 2023 al 2025, il 70 % della tariffa dal 16 ottobre; nel 2026, il 75 % di una tariffa stimata dall'8 settembre. L'anticipo sugli aiuti allo sviluppo rurale è dell'85 %. La tariffa stimata del 2026 non è quella definitiva.")),
 ('annual-rates', 'amounts', PL_LAW + ', art. 49 ust. 1', ['49'], 'https://api.sejm.gov.pl/eli/acts/DU/2025/1394',
  'Las tasas por unidad de los pagos acoplados, los ecoesquemas y el bienestar animal las fija cada año un reglamento del Ministro. Los de acoplados y ecoesquemas salieron hacia el 15 de octubre de cada campaña; los de bienestar animal, en abril del año siguiente. Las tasas definitivas del apoyo básico, el redistributivo y el de jóvenes no las hemos encontrado en el Dziennik Ustaw.', None,
  tr('Per-unit rates for coupled payments, eco-schemes and animal welfare are set each year by a ministerial regulation. Those for coupled and eco-schemes came out around 15 October of each campaign; those for animal welfare, in April of the following year. We have not found the final rates for basic support, redistributive and young-farmer payments in the Dziennik Ustaw.', "Les taux unitaires des paiements couplés, écorégimes et bien-être animal sont fixés chaque année par un règlement du ministre. Ceux des paiements couplés et des écorégimes sont parus vers le 15 octobre de chaque campagne ; ceux du bien-être animal, en avril de l'année suivante. Nous n'avons pas trouvé au Dziennik Ustaw les taux définitifs du soutien de base, du redistributif et des jeunes.", "Le tariffe unitarie dei pagamenti accoppiati, degli ecoregimi e del benessere animale le fissa ogni anno un regolamento del ministro. Quelle di accoppiati ed ecoregimi sono uscite verso il 15 ottobre di ogni campagna; quelle del benessere animale, in aprile dell'anno successivo. Non abbiamo trovato nel Dziennik Ustaw le tariffe definitive di sostegno di base, ridistributivo e giovani.")),
]
