def build(cc):
    c = COUNTRIES[cc]; rules, i18nr, ids = [], {}, set()
    for r in c['rules']:
        rid, topic, basis, arts, url, text, vals, t = r
        assert rid not in ids; ids.add(rid)
        o = {'id': rid, 'topic': topic, 'legalBasis': basis, 'articles': arts, 'text': text, 'officialUrl': url}
        if vals is not None: o['values'] = vals
        rules.append(o); i18nr[rid] = t
    cal, i18nc = [], {}
    for cid, kind, basis, arts, when, text, t in c['cal']:
        cal.append({'id': cid, 'kind': kind, 'legalBasis': basis, 'articles': arts, 'when': when, 'text': text}); i18nc[cid] = t
    ovr, i18no = [], {}
    for camp, cid, date, basis, text, t in c['ovr']:
        ovr.append({'campaign': camp, 'calendarId': cid, 'region': None, 'date': date, 'legalBasis': basis, 'text': text}); i18no['%d:%s' % (camp, cid)] = t
    ints = []
    for it in c['interventions']:
        if cc == 'FR': iid, kind, name, basis, arts, am = it; ints.append({'id': iid, 'kind': kind, 'name': name, 'nameLang': 'fr', 'legalBasis': basis, 'articles': arts, 'amounts': am})
        elif cc == 'BE': iid, kind, name, basis, arts, nl = it; ints.append({'id': iid, 'kind': kind, 'name': name, 'nameLang': nl, 'legalBasis': basis, 'articles': arts})
        else: iid, kind, name, basis, arts = it; ints.append({'id': iid, 'kind': kind, 'name': name, 'nameLang': c['lang'], 'legalBasis': basis, 'articles': arts})
    return {'schemaVersion': 1, 'country': cc, 'scheme': c['scheme'], 'status': 'CURRENT', 'curated': True, 'verifiedAt': TODAY, 'source': c['source'], 'note': c['note'],
            'interventions': ints, 'rules': rules, 'calendar': cal, 'campaignOverrides': ovr,
            'i18n': {'note': 'Traducción de Dehesa Index de las explicaciones de «rules», «calendar» y «campaignOverrides» (un resumen propio, no el texto legal). Solo es auténtico el texto oficial. Lo que no tenga traducción aquí se muestra en español.', 'rules': i18nr, 'calendar': i18nc, 'overrides': i18no}}
def main():
    for cc in ('FR', 'IT', 'PL', 'PT', 'BE', 'HR', 'EL', 'NL', 'AT', 'IE', 'RO', 'HU', 'CZ', 'SE', 'FI', 'SK', 'SI', 'EE', 'BG', 'LV'):
        doc = build(cc); p = ROOT / 'data' / 'cap' / cc.lower() / 'rules.json'
        txt = json.dumps(doc, ensure_ascii=False, indent=1) + '\n'
        if '--check' in sys.argv:
            old = json.loads(p.read_text(encoding='utf-8')); old.pop('verifiedAt'); n = json.loads(txt); n.pop('verifiedAt')
            if old != n: print('%s desactualizado: python3 scripts/build-cap-rules.py' % p); sys.exit(1)
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.exists():   # no tocar verifiedAt si no ha cambiado nada (evita commits vacios)
            old = json.loads(p.read_text(encoding='utf-8')); o2 = dict(old); n2 = json.loads(txt)
            if {k: v for k, v in old.items() if k != 'verifiedAt'} == {k: v for k, v in n2.items() if k != 'verifiedAt'}: print(cc, 'sin cambios'); continue
        p.write_text(txt, encoding='utf-8'); print('escrito', p, len(doc['rules']), 'reglas', len(doc['calendar']), 'hitos')
    if '--check' in sys.argv: print('cap rules OK')
main()
